DROP TABLE IF EXISTS `properties`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `properties` (
  `PropertyID` int NOT NULL,
  `HostID` int DEFAULT NULL,
  `PropertyTypeID` int DEFAULT NULL,
  `LocationID` int DEFAULT NULL,
  `Address` varchar(255) DEFAULT NULL,
  `Price` decimal(10,2) DEFAULT NULL,
  `Description` json DEFAULT NULL,
  `Availability` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`PropertyID`),
  KEY `PropertyTypeID` (`PropertyTypeID`),
  KEY `HostID` (`HostID`),
  KEY `LocationID` (`LocationID`),
  CONSTRAINT `properties_ibfk_1` FOREIGN KEY (`PropertyTypeID`) REFERENCES `propertytype` (`PropertyTypeID`) ON DELETE CASCADE,
  CONSTRAINT `properties_ibfk_2` FOREIGN KEY (`HostID`) REFERENCES `host` (`HostID`) ON DELETE CASCADE,
  CONSTRAINT `properties_ibfk_3` FOREIGN KEY (`LocationID`) REFERENCES `location` (`LocationID`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

